const AGES={young:{n:"若年層"},mid:{n:"ミドル層"},pre:{n:"プレリタイア層"},retire:{n:"リタイア層"}};
const WEALTH_STAGE={form:{n:"形成期"},peak:{n:"ピーク期"},prep:{n:"承継準備期"},exec:{n:"承継実行期"}};
const HHS={single:{n:"単身世帯"},couple:{n:"夫婦世帯"},family:{n:"ファミリー世帯"},withchild:{n:"子と同居"}};
const OCC={owner:{n:"事業オーナー（現役）"},retiredOwner:{n:"引退オーナー"},pro:{n:"給与所得者・専門職"},landlord:{n:"承継・地主"}};
const ORIGIN={self:{n:"自力形成"},inherit:{n:"相続・贈与による取得"}};
const HOUSING={rent:{n:"賃貸"},own:{n:"持家"}};
const INVEST={none:{n:"預金・現金が中心"},started:{n:"投資信託・株式などを運用中"}};
const TIERS={
  mass:{n:"マス層",tint:"var(--mass)",soft:"var(--mass-soft)",hex:"#7CAE93"},
  upper:{n:"アッパーマス層",tint:"var(--upper)",soft:"var(--upper-soft)",hex:"#E0A05F"},
  wealth:{n:"富裕層",tint:"var(--wealth)",soft:"var(--wealth-soft)",hex:"#B489C4"}
};
const CAT=[["ins","保険"],["loan","ローン"],["inv","投資・資産形成"],["pay","決済・ポイント"],["etc","その他"]];

function classifyTier(assets){
  return assets<3000 ? "mass" : assets<10000 ? "upper" : "wealth";
}
function classifyAgeBand(age){
  return age<40 ? "young" : age<50 ? "mid" : age<65 ? "pre" : "retire";
}
function classifyWealthStage(age){
  return age<50 ? "form" : age<60 ? "peak" : age<70 ? "prep" : "exec";
}

function classify(a){
  const tier=classifyTier(a.assets);
  if(tier==="wealth"){
    const stage=classifyWealthStage(a.age);
    const grid={owner:["W01","W02","W03","W04"],retiredOwner:["W05","W06","W07","W08"],pro:["W09","W10","W11","W12"],landlord:["W13","W14","W15","W16"]};
    const idx={form:0,peak:1,prep:2,exec:3}[stage];
    return {tier,stage,id:grid[a.occupation][idx]};
  }
  const ageBand=classifyAgeBand(a.age);
  const isCouple = a.hh==="couple";
  let id;
  if(tier==="mass"){
    if(ageBand==="young"){
      if(a.hh==="single") id = a.invest==="started" ? "M02" : "M01";
      else if(isCouple) id = a.housing==="own" ? "M04" : "M03";
      else id = a.housing==="own" ? "M06" : "M05";
    }else if(ageBand==="mid"){
      if(a.hh==="single") id="M07";
      else if(isCouple) id="M08";
      else id = (a.childAge!=null && a.childAge<=15) ? "M09" : "M10";
    }else if(ageBand==="pre"){
      if(a.hh==="single") id="M11";
      else if(isCouple) id="M12";
      else id="M13";
    }else{
      if(a.hh==="single") id="M14";
      else if(isCouple) id="M15";
      else id="M16";
    }
  }else{
    const inherited = a.origin==="inherit";
    if(ageBand==="young"){
      if(a.hh==="single") id="U01";
      else if(isCouple) id="U02";
      else id="U03";
    }else if(ageBand==="mid"){
      if(a.hh==="single") id="U08";
      else if(isCouple) id = inherited?"U05":"U04";
      else id = inherited?"U07":"U06";
    }else if(ageBand==="pre"){
      if(a.hh==="single") id="U09";
      else if(isCouple) id = inherited?"U11":"U10";
      else id = inherited?"U13":"U12";
    }else{
      if(a.hh==="single") id="U14";
      else if(isCouple) id = inherited?"U16":"U15";
      else id = inherited?"U18":"U17";
    }
  }
  return {tier,ageBand,id};
}

function fmtAsset(v){
  return v>=10000 ? (v/10000).toFixed(v%10000===0?0:1)+"億円" : v.toLocaleString("ja-JP")+"万円";
}

function getIllustration(a,result){
  return ILL[result.id];
}

